using System.Security.Cryptography;using System.Text;namespace QuantForge.Core;public sealed record AndroidResearchLaunchPreview(string PreviewFingerprint,string DraftFingerprint,string DatasetSelectionFingerprint,string StrategySelectionFingerprint,bool ReadyToPrepare,string Status,bool CanSubmitOrders);public static class AndroidResearchLaunchPreviewRules{public static AndroidResearchLaunchPreview Create(StrategyDraft draft,StrategyDraftReview review,AndroidDatasetSelection dataset,AndroidStrategySelection strategy,AndroidResearchReadinessCard readiness){StrategyDraftRules.Validate(draft);if(review.DraftFingerprint!=draft.DraftFingerprint)throw new InvalidOperationException("Launch preview review does not match strategy draft.");if(strategy.StrategyFingerprint!=draft.SourceFingerprint)throw new InvalidOperationException("Launch preview strategy selection does not match strategy draft.");if(dataset.DatasetFingerprint!=readiness.DatasetFingerprint||strategy.StrategyFingerprint!=readiness.StrategyFingerprint)throw new InvalidOperationException("Launch preview selections do not match readiness evidence.");var ready=review.ReadyForResearch&&readiness.Ready;var status=ready?"Ready to prepare simulation-only research.":"Blocked by incomplete research readiness.";var text=string.Join("|",draft.DraftFingerprint,dataset.SelectionFingerprint,strategy.SelectionFingerprint,readiness.DatasetFingerprint,readiness.StrategyFingerprint,ready);var fp=Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(text)));return new(fp,draft.DraftFingerprint,dataset.SelectionFingerprint,strategy.SelectionFingerprint,ready,status,false);}}
